<script lang="ts">
 import {adminClinicsApi} from '#lib/api/admin/clinics.ts';import {apiMessage} from '#lib/admin/scheduling.ts';import {PLAN_LABELS,isExpired,daysUntilExpiry} from '#lib/feature-access.ts';import {FACILITY_TYPE_LABELS} from '#lib/constants/clinic-constants.ts';import {Button} from '#lib/components/ui/button/index.ts';import Feedback from './Feedback.svelte';import type {MedicalFacility,SubscriptionPlan,FacilityType} from '#lib/types/clinic.ts';
 let rows=$state<MedicalFacility[]>([]),loading=$state(true),error=$state(''),revision=$state(0);$effect(()=>{const r=revision;void r;let live=true;loading=true;error='';adminClinicsApi.list().then(v=>{if(live)rows=v;}).catch(e=>{if(live)error=apiMessage(e,'院所概況載入失敗');}).finally(()=>{if(live)loading=false;});return()=>{live=false;};});
 const stats=$derived([{label:'總院所數',value:rows.length},{label:'啟用中院所',value:rows.filter(f=>f.is_active).length},{label:'有效付費院所',value:rows.filter(f=>f.subscription_plan!=='free'&&f.subscription_status==='active'&&!isExpired(f.subscription_expires_at)).length},{label:'7 天內到期',value:rows.filter(f=>{const d=daysUntilExpiry(f.subscription_expires_at);return d!==null&&d>=0&&d<=7;}).length}]);
</script>
<div class="space-y-6"><div class="flex items-center justify-between gap-3"><div><h1 class="text-2xl font-semibold">總覽</h1><p class="mt-1 text-sm text-muted-foreground">全平台院所與訂閱概況</p></div><Button href="/admin/clinics">管理院所</Button></div><Feedback {error}/>{#if error}<Button variant="outline" onclick={()=>revision++}>重試總覽</Button>{/if}{#if loading}<p role="status">載入平台概況中…</p>{:else if !error}<div class="grid grid-cols-2 gap-3 lg:grid-cols-4">{#each stats as s (s.label)}<div class="rounded-2xl border bg-card p-5"><h2 class="text-sm text-muted-foreground">{s.label}</h2><p class="mt-3 text-3xl font-semibold">{s.value}</p></div>{/each}</div><div class="grid gap-4 lg:grid-cols-2"><section class="space-y-4 rounded-2xl border bg-card p-5"><h2 class="font-semibold">登記方案分布</h2>{#each Object.entries(PLAN_LABELS) as [key,label] (key)}<div class="flex justify-between text-sm"><span>{label}</span><span>{rows.filter(f=>f.subscription_plan===key as SubscriptionPlan).length} 間</span></div>{/each}</section><section class="space-y-4 rounded-2xl border bg-card p-5"><h2 class="font-semibold">院所類型分布</h2>{#each Object.entries(FACILITY_TYPE_LABELS) as [key,label] (key)}<div class="flex justify-between text-sm"><span>{label}</span><span>{rows.filter(f=>f.facility_type===key as FacilityType).length} 間</span></div>{/each}</section></div><section class="space-y-3 rounded-2xl border bg-card p-5"><h2 class="font-semibold">最近加入院所</h2>{#each [...rows].sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,5) as f (f.id)}<a href={'/admin/clinics/'+f.id} class="flex flex-wrap items-center justify-between gap-3 rounded-xl p-3 hover:bg-muted"><span class="font-medium">{f.name}</span><span class="text-sm text-muted-foreground">{f.created_at.slice(0,10)} · {PLAN_LABELS[f.subscription_plan]} · {f.is_active?'啟用':'停用'}</span></a>{:else}<p class="text-muted-foreground">尚無院所。</p>{/each}</section>{/if}</div>
